# Word frequency comparison: cut vs finished in baseline
import json, re, collections
rows = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
def words(t):
    return re.findall(r"[A-Za-z']+", t.lower())
cut_words = collections.Counter(); fin_words = collections.Counter()
cut_tok = fin_tok = 0
for r in rows:
    ws = words(r['text'])
    if r['finish']=='length':
        cut_words.update(ws); cut_tok += r['tokens']
    else:
        fin_words.update(ws); fin_tok += r['tokens']
print('cut_tok', cut_tok, 'fin_tok', fin_tok)
vocab = set(cut_words) | set(fin_words)
diffs = []
for w in vocab:
    c = cut_words[w]/cut_tok*1000; f = fin_words[w]/fin_tok*1000
    if c+f > 0.05:
        diffs.append((c-f, c, f, w))
diffs.sort(reverse=True)
for d in diffs[:25]:
    print(f'{d[3]:15s} cut={d[1]:.3f} fin={d[2]:.3f} diff={d[0]:.3f}')

